const fs = require('fs').promises;
const path = require('path');
const { listExportFiles } = require('./files');

async function resolveImportFiles(importPath, deps = {}) {
  const fsPromises = deps.fs || fs;
  const logger = deps.logger;
  const stats = await fsPromises.stat(importPath);

  if (stats.isDirectory()) {
    const files = await listExportFiles(importPath, { ...deps, logger });
    return {
      filesToImport: files.map((file) => file.filepath),
      exportDir: importPath
    };
  }

  return {
    filesToImport: [importPath],
    exportDir: path.dirname(importPath)
  };
}

module.exports = {
  resolveImportFiles
};
